<?php declare(strict_types=1);use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;$years=[];foreach($rows as$r)$years[]=substr((string)$r['report_date'],0,4);$years=array_values(array_unique($years));sort($years);$yearOptions=['all'=>'Все годы','none'=>'Без года'];foreach($years as$year)$yearOptions[$year]=$year;$query=Yii::$app->request->get();$rub=static fn(int$c)=>number_format($c/100,2,',',' ').' ₽';ViewSupport::begin($this,'Расчёты ОТиЗ',$identity,'otiz','wide');?>
<main class="fm2-otiz fm2-otiz-page"><section class="fm2-otiz-surface"><div class="fm2-otiz-tabs-surface"><?=$this->render('_otiz-nav',['current'=>'payments'])?></div></section><header class="fm2-page-header"><div><h1>Расчёты ОТиЗ</h1><p>Единый реестр черновиков, обязательств и истории выплат</p></div><form method="post" action="/pilot/otiz/calculations"><input type="hidden" name="_csrf" value="<?=Html::encode($csrf)?>"><input type="hidden" name="operationId" value="<?=ViewSupport::uuid()?>"><label>Расчётная дата<input class="shlz-input" type="date" name="reportDate" required></label><button class="shlz-button shlz-button--primary">Новый расчёт</button></form></header>
<?php if(($query['error']??'')==='empty'):?><p class="shlz-alert" role="status">Новых работ для расчёта нет. <a href="/pilot/otiz/payments?filter=waiting&amp;year=all">Перейти к ожидающим выплатам</a>.</p><?php endif?>
<nav class="fm2-otiz-v2-tabs" aria-label="Фильтры расчётов"><?php foreach(['waiting'=>'Ожидают выплаты','drafts'=>'Черновики','history'=>'История','all'=>'Все']as$key=>$label):?><a href="?filter=<?=$key?>&amp;year=<?=Html::encode((string)($query['year']??'all'))?>"><?=$label?></a><?php endforeach?></nav><form method="get" action="/pilot/otiz/payments"><input type="hidden" name="filter" value="<?=Html::encode((string)($query['filter']??'waiting'))?>"><?=ViewSupport::choice('year',(string)($query['year']??'all'),$yearOptions,'Год')?><button class="shlz-button shlz-button--secondary">Показать</button></form>
<section class="fm2-otiz-surface"><div class="shlz-table-wrap" tabindex="0"><table class="shlz-table"><thead><tr><th>Расчёт</th><th>Дата</th><th>Автор</th><th>Статус</th><th>Сумма</th><th>Выплачено</th><th>Остаток / причина</th></tr></thead><tbody><?php foreach($rows as$r):$p=is_array($r['projection']??null)?$r['projection']:json_decode((string)$r['projection_json'],true);$sum=(int)($p['totalCents']??0);$reason=(string)($r['blocking_reason']??$p['blockingReason']??'');$status=(string)$r['status'];$state=match($status){'draft'=>'Черновик','accepted'=>'Утверждён','cancelled'=>'Отменён',default=>'Нет данных'};$amountLabel=match($status){'draft'=>'Предварительно к выплате','accepted'=>'Утверждено к выплате',default=>'Сохранённая сумма'};?><tr><td><a href="/pilot/otiz/calculations/<?=(int)$r['id']?>">Расчёт #<?=(int)$r['id']?></a></td><td><?=Html::encode((string)$r['report_date'])?></td><td><?=Html::encode((string)($r['author_name']??$r['actor_user_id']??'Нет данных'))?></td><td><?=$state?></td><td><span><?=$amountLabel?></span><br><strong><?=$rub($sum)?></strong></td><td><?=$rub((int)($r['paid_cents']??0))?></td><td><?=$rub(max(0,$sum-(int)($r['paid_cents']??0)))?><?php if($reason!==''):?> · <?=Html::encode($reason)?><?php elseif($status==='cancelled'):?> · расчёт отменён<?php endif?></td></tr><?php endforeach?></tbody></table></div></section><?=ViewSupport::pagination('/pilot/otiz/payments',$page,$pages,$total,$pageSize,['filter'=>$query['filter']??'waiting','year'=>$query['year']??'all'],'Страницы расчётов ОТиЗ')?></main><?php ViewSupport::end($this);?>
